import type { TrackDirection, TimingLineType } from "@/db/types";

type NullableCoordinate = {
  latitude: number | null;
  longitude: number | null;
};

export type TrackSeed = {
  track: {
    id: string;
    slug: string;
    name: string;
    country: string | null;
    // ISO 3166-1 alpha-2, used for grouping and localized country names.
    countryCode: string | null;
    location: string | null;
    layoutName: string | null;
    lengthMeters: number | null;
    corners: number | null;
    direction: TrackDirection | null;
    centerLatitude: number | null;
    centerLongitude: number | null;
    // Closed [lat, lng] ring tracing the track centerline.
    path?: [number, number][];
    // Surface width the outline is drawn at, when the default does not suit.
    pathWidthMeters?: number;
  };
  timingLines: {
    id: string;
    trackId: string;
    name: string;
    type: TimingLineType;
    seq: number;
    a: NullableCoordinate;
    b: NullableCoordinate;
  }[];
};

